use crate::{core::atlas::{phase_b,phase_e},model::{span,CaseData,Mark,Query}};
pub fn fold_c(data:&CaseData,q:&Query,mark:&Mark)->Option<Vec<String>>{if !phase_e(data,&mark.zone,&q.name){return None} let signer=phase_b(data,&mark.zone,&mark.signer,q.instant)?; let bridge=data.bridges.iter().find(|b|b.zone==mark.zone&&b.child==signer.id&&span(q.instant,b.start,b.end))?; let issuer=phase_b(data,&mark.zone,&bridge.issuer,q.instant)?; let root=data.roots.iter().find(|r|r.zone==mark.zone&&r.child==issuer.id&&span(q.instant,r.start,r.end))?; Some(vec![format!("root:{}->{}",root.zone,issuer.id),format!("{}->{}",issuer.id,signer.id),format!("{}->{}",signer.id,mark.name)])}
